Use the diagram to write the shaded amount as a mixed number and an improper fraction. Each grid represents one whole.
[tikz]% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[{"name":"templateShade","hex":"D4E8FF","reason":"Shading identifies the four quarters comprising one whole."}],"reference":"template visual-whole"}
\begin{tikzpicture}[x=1mm,y=1mm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{templateShade}{HTML}{D4E8FF}
\path[use as bounding box] (-0.6,-24.6) rectangle (24.6,0.6);
\fill[templateShade] (0,-12) rectangle (12,0);
\fill[templateShade] (12,-12) rectangle (24,0);
\fill[templateShade] (0,-24) rectangle (12,-12);
\fill[templateShade] (12,-24) rectangle (24,-12);
\draw[black,line width=0.4pt] (12,0)--(12,-24);
\draw[black,line width=0.4pt] (0,-12)--(24,-12);
\draw[black,line width=0.8pt] (0,0) rectangle (24,-24);
\end{tikzpicture}[/tikz]
[tikz]% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[{"name":"templateShade","hex":"D4E8FF","reason":"Shading identifies the three additional quarters to count."}],"reference":"template visual-three-quarters"}
\begin{tikzpicture}[x=1mm,y=1mm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{templateShade}{HTML}{D4E8FF}
\path[use as bounding box] (-0.6,-24.6) rectangle (24.6,0.6);
\fill[templateShade] (0,-12) rectangle (12,0);
\fill[templateShade] (12,-12) rectangle (24,0);
\fill[templateShade] (0,-24) rectangle (12,-12);
\draw[black,line width=0.4pt] (12,0)--(12,-24);
\draw[black,line width=0.4pt] (0,-12)--(24,-12);
\draw[black,line width=0.8pt] (0,0) rectangle (24,-24);
\end{tikzpicture}[/tikz]
